import org.openqa.selenium.By;
import org.openqa.selenium.WebDriver;
import org.openqa.selenium.chrome.ChromeDriver;
import org.junit.Test;

public class SulzerChangeoverTest {
    @Test
    public void testSulzerChangeover() {
        WebDriver driver = new ChromeDriver();
        driver.get("https://gc-dev.centralindia.cloudapp.azure.com/ambica/master-data/sulzer-changeover");
        driver.findElement(By.xpath("//button[contains(text(), 'Master Data')]")).click();
        driver.findElement(By.xpath("//a[contains(text(), 'Sulzer Changeover')]")).click();
        driver.findElement(By.xpath("//button[contains(text(), 'FC Knotting')]")).click();
        driver.findElement(By.cssSelector("input[placeholder='DD:HH:MM:SS']")).clear();
        driver.findElement(By.cssSelector("input[placeholder='DD:HH:MM:SS']")).sendKeys("00:00:00:12");
        driver.findElement(By.xpath("//button[contains(text(), 'Save')]")).click();
        driver.quit();
    }
}
